    // Use padding to avoid bank conflicts
    __shared__ float As[TILE_SIZE][TILE_SIZE+1];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE+1];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Each thread computes a 2x2 tile
    int row = by * TILE_SIZE + ty * SUB_TILE_SIZE;
    int col = bx * TILE_SIZE + tx * SUB_TILE_SIZE;

    float sum[SUB_TILE_SIZE][SUB_TILE_SIZE] = {{0.0f}};

    for (int t = 0; t < N; t += TILE_SIZE) {
        // Load tile of A into shared memory (coalesced access)
        for (int i = 0; i < SUB_TILE_SIZE; i++) {
            int load_row = ty * SUB_TILE_SIZE + i;
            int a_row = by * TILE_SIZE + load_row;
            if (a_row < N && (t + tx) < N) {
                As[load_row][tx] = A[a_row * N + t + tx];
            } else {
                As[load_row][tx] = 0.0f;
            }
        }

        // Load tile of B into shared memory (coalesced access)
        for (int i = 0; i < SUB_TILE_SIZE; i++) {
            int load_col = tx * SUB_TILE_SIZE + i;
            int b_col = bx * TILE_SIZE + load_col;
            if (b_col < N && (t + ty) < N) {
                Bs[ty][load_col] = B[(t + ty) * N + b_col];
            } else {
                Bs[ty][load_col] = 0.0f;
            }
        }

        __syncthreads();

        // Compute partial products
        for (int k = 0; k < TILE_SIZE; k++) {
            for (int i = 0; i < SUB_TILE_SIZE; i++) {
                float a_val = As[ty * SUB_TILE_SIZE + i][k];
                for (int j = 0; j < SUB_TILE_SIZE; j++) {
